import math
from collections import defaultdict

def solve(n):
    # Find all divisors greater than 1
    divisors = []
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divisors.append(i)
            if i != n // i:
                divisors.append(n // i)
    divisors.append(n)
    divisors.sort()

    # Group divisors by their prime factors
    prime_to_divisors = defaultdict(list)

    def get_prime_factors(num):
        temp = num
        factors = set()
        d = 2
        while d * d <= temp:
            if temp % d == 0:
                factors.add(d)
                while temp % d == 0:
                    temp //= d
            d += 1
        if temp > 1:
            factors.add(temp)
        return factors

    for d in divisors:
        factors = get_prime_factors(d)
        for p in factors:
            prime_to_divisors[p].append(d)

    # Build arrangement based on prime factor coverage
    # Use the prime factor decomposition to guide ordering
    primes = list(prime_to_divisors.keys())

    # If we have relations between primes via divisors divisible by multiple
    # Try to arrange divisors to maximize gcd with neighbors

    # Simple greedy approach: arrange by which primes they share
    # Build groups by shared primes first

    result = []
    max_coverage = 0
    best_order = None

    for order in [(divisors[i:] + divisors[:i]) for i in range(len(divisors))]:
        # Check how many adjacent pairs have gcd > 1
        moves = 0
        for i in range(len(order) - 1):
            if gcd(order[i], order[i+1]) == 1:
                moves += 1
        if moves <= max_coverage:
            max_coverage = moves
            best_order = order

    return best_order, max_coverage

