def solution(input_str):
    """
    Game theory problem: Two players play on an n×m matrix.
    Ashish goes first; they alternate turns reducing cells.

    The winning condition follows Nim-like XOR properties:
    If the XOR sum of all cell values is non-zero, first player (Ashish) wins.
    If the XOR sum is 0, second player (Jeel) wins.

    This works because each cell can be treated independently in the game 
    theory model, and XOR arithmetic captures the winning positions.
    """
    if not input_str or not input_str.strip():
        return ""

    input_data = input_str.strip().split()
    if not input_data:
        return ""

    iterator = iter(input_data)
    results = []

    try:
        t = int(next(iterator))

        for _ in range(t):
            n = int(next(iterator))
            m = int(next(iterator))

            xor_sum = 0
            for i in range(n):
                for j in range(m):
                    val = int(next(iterator))
                    xor_sum ^= val

            if xor_sum != 0:
                results.append("Ashish")
            else:
                results.append("Jeel")

        return "\n".join(results)

    except StopIteration:
        return ""


