def solution(input_data):
    lines = input_data.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))

    MOD = 1000000007

    used = set()
    for x in a:
        if x != -1:
            used.add(x)

    unknown_positions = [i + 1 for i in range(n) if a[i] == -1]  # 1-indexed positions
    available_values = [v for v in range(1, n + 1) if v not in used]  # available values

    m = len(unknown_positions)

    # For each available value available_values[i], check if it "forbids" unknown_positions[i]
    forbidden = [unknown_positions[i] == available_values[i] for i in range(m)]

    # DP: after i steps, dp[j] = ways with j unconstrained positions remaining
    dp = [0] * (m + 1)
    dp[m] = 1

    for i in range(m):
        new_dp = [0] * (m + 1)
        for j in range(m + 1):
            if dp[j] == 0:
                continue

            if forbidden[i]:
                # This value forbids one specific position (creating fixed point if matched)
                # Either skip (place in free position, still need 1 more fixed avoidance): j stays
                # Or use it on the fixed position (becomes valid assignment, j decreases by 1)
                new_dp[j] = (new_dp[j] + dp[j]) % MOD
                if j > 0:
                    new_dp[j - 1] = (new_dp[j - 1] + dp[j]) % MOD
            else:
                # Not forbidden, free to place anywhere (decreases unconstrained)
                if j > 0:
                    new_dp[j - 1] = (new_dp[j - 1] + dp[j]) % MOD

        dp = new_dp

    return str(dp[0])

