def solution(s):
    lines = s.strip().split('\n')
    n = int(lines[0])

    # Edge case: single node
    if n == 1:
        return '1'

    # Parse edges and build adjacency list
    adj = [[] for _ in range(n + 1)]
    for i in range(1, n):
        u, v = map(int, lines[i].split())
        adj[u].append(v)
        adj[v].append(u)

    # BFS to establish parent-child relationships and processing order
    parent = [0] * (n + 1)
    order = []
    stack = [1]
    visited = [False] * (n + 1)
    visited[1] = True

    while stack:
        u = stack.pop()
        order.append(u)
        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                parent[v] = u
                stack.append(v)

    # Process nodes in reverse order (bottom-up from leaves to root)
    reversed_order = order[::-1]

    # Build children list for easier processing
    children = [[] for _ in range(n + 1)]
    for u in order:
        for v in adj[u]:
            if v != parent[u]:
                children[u].append(v)

    # dp[u] is a list where dp[u][sz] = max product with u's component size = sz
    dp = [None] * (n + 1)

    for u in reversed_order:
        # Start with u as a component of size 1, product 1
        dp[u] = [0] * (n + 1)
        dp[u][1] = 1

        for v in children[u]:
            child_dp = dp[v]
            current_dp = dp[u].copy()

            # Find the maximum product we can get from v's subtree (cut edge case)
            max_from_v = max(child_dp[i] for i in range(1, n + 1) if child_dp[i] > 0) or 0

            # Try all possible merges: don't cut the edge, merge components
            for sz_u in range(1, n + 1):
                if current_dp[sz_u] == 0:
                    continue
                for sz_v in range(1, n + 1 - sz_u + 1):
                    if child_dp[sz_v] == 0:
                        continue
                    new_sz = sz_u + sz_v
                    prod = current_dp[sz_u] * child_dp[sz_v]
                    if prod > current_dp[new_sz]:
                        current_dp[new_sz] = prod

            # After considering cutting option for this child:
            for sz in range(1, n + 1):
                # If we close the edge to v, product is current_dp[sz] * max_from_v
                if max_from_v > 0 and current_dp[sz] * max_from_v > dp[u][sz]:
                    dp[u][sz] = current_dp[sz] * max_from_v

            # Keep the best merge products
            for sz in range(1, n + 1):
                if current_dp[sz] > dp[u][sz]:
                    dp[u][sz] = current_dp[sz]

    # Find the maximum product for the root's component of any size
    ans = max(dp[1])
    return str(ans)

