from collections import deque, defaultdict

def solution(graph_edges):
    lines = graph_edges.strip().split('\n')
    if not lines or not lines[0]:
        return '0'

    N = int(lines[0])
    if N == 0:
        return '0'
    if N == 1:
        return '1'

    adj = [[] for _ in range(N)]

    for line in lines[1:]:
        if not line.strip():
            continue
        parts = line.split()
        if len(parts) >= 2:
            try:
                u, v = int(parts[0]), int(parts[1])
                if 0 <= u < N and 0 <= v < N:
                    adj[u].append(v)
                    adj[v].append(u)
            except ValueError:
                continue

    max_total = 0

    # Try each node as potential starting point
    for start_node in range(N):
        # BFS to get traversal order
        visited = {start_node}
        order = [start_node]
        queue = deque([start_node])

        while queue:
            node = queue.popleft()
            for neighbor in adj[node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    order.append(neighbor)
                    queue.append(neighbor)

        # Calculate total potential for this ordering
        # When we power a node, it can reach unpowered neighbors
        powered = [False] * N
        powered[start_node] = True

        total_potential = 0

        for node in order:
            # Count unpowered cores this node can reach
            # BFS from current node, only visiting unpowered cores
            count = 0
            stack = [node]
            local_visited = {node}

            while stack:
                curr = stack.pop()
                count += 1
                for neighbor in adj[curr]:
                    if neighbor not in local_visited and not powered[neighbor]:
                        local_visited.add(neighbor)
                        stack.append(neighbor)

            # The potential equals what this node can power at this moment
            # Plus what it can still power through newly powered nodes
            # For simplicity, count just locally reachable unpowered
            if not powered[node]:
                # Node hasn't been powered yet, shouldn't happen in our order
                continue

            total_potential += count
            powered[node] = True

        max_total = max(max_total, total_potential)

    return str(max_total)

