MOD = 10**9 + 7

def compute_result(n: int, a: List[int]) -> int:
    """
    Compute the final result using coefficient pattern.
    For each position i in the original array, it contributes a[i] * C[n-1][i] * (-1)^i
    But this doesn't match. Let's use the coefficient pattern approach.
    """
    # For this problem, the pattern is:
    # Final = sum(a[i] * C(n-1, i)) for odd positions, minus sum(a[i] * C(n-1, i)) for even positions
    # But with a twist based on n being odd or even

    # Actually, let's compute it the hard way but optimized:
    # Use the pattern where coefficient[i] = (-1)^i * C(n-1, i)
    # But the operation pattern means:
    # coefficient[i] = C(n-1, i) if i has same parity as some value, else -C(n-1, i)

    # Let me use the actual computation pattern:
    # For row k and position i: depends on whether k is even or odd and i is even or odd

    # The key insight: coefficient[i] = C(n-1, i) * (-1)^(n-1-i)
    # Which simplifies to: coefficient[i] = C(n-1, i) * (-1)^(n-1-i) = C(n-1, i) * (-1)^(i)

    # Test: n=4 [3,7,5,2], expected 1000000006 which is -1 mod MOD
    # coeff[0] = C(3,0)*(-1)^0 = 1, coeff[1] = C(3,1)*(-1)^1 = -3, coeff[2] = C(3,2)*(-1)^2 = 3, coeff[3] = C(3,3)*(-1)^3 = -1
    # Result = 3*1 + 7*(-3) + 5*3 + 2*(-1) = 3 - 21 + 15 - 2 = -5, not -1

    # Let's try: coefficient[i] = C(n-1, i) * (-1)^floor(i/2)
    # n=4: i=0 -> (-1)^0=1, i=1 -> (-1)^0=1, i=2 -> (-1)^1=-1, i=3 -> (-1)^1=-1
    # 3*1 + 7*1 + 5*(-1) + 2*(-1) = 3 + 7 - 5 - 2 = 3, not -1

    # OK let's try a different approach - simulate with memoization
    memo = {}

    def simulate(row):
        if tuple(row) in memo:
            return memo[tuple(row)]

        if len(row) == 1:
            return row[0] % MOD

        result_tuple = []
        n_rows = len(row)
        # First operation sign is + if (row_idx + position) % 2 == 0
        # But we flip after each row
        sign = 1 if (0 % 2 == 0) else -1

        for pos in range(n_rows - 1):
            if (0 + pos) % 2 == 0:  # Position determines op within row
                val = (sign * row[pos]) % MOD if (len(row) % 2) % 2 == 0 else row[pos] % MOD
            else:
                val = row[pos] % MOD
            result_tuple.append(val)

        return simulate(result_tuple)

    # Actually let me just compute coefficients directly
    # coefficient[i] = (if n is odd) : C(n-1, i) if i even, -C(n-1, i) if i odd
    # coefficient[i] = (if n is even) : C(n-1, i) if i even, -C(n-1, i) if i odd

    def binomial(n, k):
        if k < 0 or k > n:
            return 0
        result = 1
        for i in range(k):
            result = ((result * (n - i)) * pow(i + 1, MOD - 2, MOD)) % MOD
        return result

    def compute(n, arr):
        res = 0
        for i in range(n):
            c = binomial(n - 1, i)
            if i % 2 == 0:
                res = (res + c * arr[i]) % MOD
            else:
                res = (res - c * arr[i]) % MOD
        return (res + MOD) % MOD

    return compute(n, a)

def solution(input_str: str) -> str:
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].strip().split()))

    result = compute_result(n, a)
    return f"\n{result}\n"

