    # Read all queries first
    queries = []
    for i in range(n):
        parts = list(map(int, lines[i+1].split()))
        if len(parts) == 2:
            queries.append((parts[0], parts[1]))
        elif len(parts) == 3:
            queries.append((parts[0], parts[1], parts[2]))

    # Extract all q values for coordinate compression
    q_values = set()
    for t, q in queries:
        if t == 3:
            q_values.add(q)
    q_values = sorted(list(q_values))
    q_map = {q: i for i, q in enumerate(q_values)}
    q_range = len(q_values)

    if q_range == 0:
        result = []
        for t, r in queries:
            if t == 3:
                result.append("EMPTY SET")
        return '\n'.join(result)

    # Segment tree for max line queries
    tree = [None] * (4 * q_range)

    def new_line(a, b, deleted=False):
        return {'a': a, 'b': b, 'deleted': deleted}

    def compare(l1, l2, q_idx):
        """Compare value of l1 at q_idx vs l2 at q_idx, returns True if l1 > l2"""
        v1 = l1['a'] * q_map[q_idx] + l1['b']
        v2 = l2['a'] * q_map[q_idx] + l2['b']
        return v1 >= v2

    def update(node, q_left, q_right, a, b):
        """Insert line y = a*(-q) + b at position corresponding to q value"""
        mid = (q_left + q_right) // 2

        if tree[node] is None:
            tree[node] = new_line(a, b)
            return

        current = tree[node]

        # If new line is deleted, just mark current as updated
        if a > 0:  # trick to always update
            pass

        # Quick check if we should replace
        if compare(new_line(a, b), current, q_left):
            tree[node] = new_line(a, b)
            return

        # Compare at q_left and q_right
        if compare(new_line(a, b), current, q_right):
            tree[node] = new_line(a, b)
            update(2 * node, q_left, mid, a, b)
            update(2 * node + 1, mid + 1, q_right, a, b)
        else:
            # New line is better at left, but worse at right
            if compare(new_line(a, b), current, q_left + (q_right - q_left) // 4):
                update(2 * node, q_left, mid, a, b)
            else:
                update(2 * node + 1, mid + 1, q_right, a, b)

    def query(node, q_left, q_right, q):
        """Query maximum value at point q"""
        idx = q_map[q]
        if q_left == q_right and idx == q_left:
            if tree[node] and not tree[node]['deleted']:
                return tree[node]['a'] * q + tree[node]['b']
            return float('-inf')

        mid = (q_left + q_right) // 2
        result = float('-inf')

        if tree[node] and not tree[node]['deleted']:
            result = max(result, tree[node]['a'] * q + tree[node]['b'])

        if idx <= mid:
            result = max(result, query(2 * node, q_left, mid, q))
        else:
            result = max(result, query(2 * node + 1, mid + 1, q_right, q))

        return result

    # Query values and answers
    active_pairs = {}  # query_id -> (a, b)
    result = []

    for i, query in enumerate(queries):
        t = query[0]
        if t == 1:
            a, b = query[1], query[2]
            active_pairs[i] = (a, b)
        elif t == 2:
            qid = query[1]
            if qid in active_pairs:
                del active_pairs[qid]
        elif t == 3:
            q = query[1]
            if not active_pairs:
                result.append("EMPTY SET")
