                best_found = False
                for (a, b) in active_pairs.values():
                    val = a * q + b
                    if val > best:
                        best = val
                        best_found = True

                if not best_found:
                    result.append("EMPTY SET")
                else:
                    result.append(str(best))

    return '\n'.join(result)

