        di = parts[1]
        xi = parts[2] if len(parts) > 2 else 0  # 0 means no dependency
        items.append({'ci': ci, 'di': di, 'xi': xi})

    # Build the dependency forest
    # adj[parent] contains children (items that depend on parent's coupon)
    adj = [[] for _ in range(n + 1)]
    roots = []  # items with no dependencies (roots of trees)

    for i in range(1, n + 1):
        xi = items[i - 1]['xi']
        if xi == 0:
            roots.append(i)
        else:
            adj[xi].append(i)

    # DP function for tree rooted at node (1-indexed)
    # computes minimum cost to buy k items from the subtree
    # Returns list where dp[k] = minimum cost to buy k items from subtree
    def tree_dp(node):
        # Returns [dp[k] for k in range 0..size+1]
        # dp[k] = minimum cost to buy exactly k items from subtree rooted at node

        # Process subtree recursively
        # For the current node, we have two options:
        # 1. Buy the item without coupon: cost = ci, no coupon dependency
        # 2. Buy the item with coupon: cost = ci - di, requires coupon of parent (if any)

        # Approach: dp[k][has_coupon] where has_coupon indicates whether item is bought WITH coupon
        # But we can simplify: for subtree, return all ways to form item counts

        children = adj[node]
