            # Leaf node
            return {0: 0, 1: min(items[node - 1]['ci'], items[node - 1]['ci'] - items[node - 1]['di'])}

        # Combine results from all subtrees
        # Start with just current node
        result = {}
        ci = items[node - 1]['ci']
        di = items[node - 1]['di']

        # Option: don't buy current item
        result[0] = 0

        # Option: buy current item with coupon (if possible - always possible at root of subtree)
        result[1] = ci - di

        # We'll use iterative merging
        def merge(prev_result, subtree_result):
            new_result = {}
            for prev_k, prev_cost in prev_result.items():
                for k2, cost2 in subtree_result.items():
                    new_k = prev_k + k2
                    new_cost = prev_cost + cost2
                    if new_k not in new_result or new_result[new_k] > new_cost:
                        new_result[new_k] = new_cost
            return new_result

        # Process each child
