        for k1, v1 in dp1.items():
            for k2, v2 in dp2.items():
                new_k = k1 + k2
                v = v1 + v2
                if new_k not in new_dp or new_dp[new_k] > v:
                    new_dp[new_k] = v
        return new_dp

    for root in roots:
        child_result = tree_dp(root)
        total_result = merge(total_result, child_result)

    # Find maximum k such that cost <= b
    max_items = 0
    for k in reversed(sorted(total_result.keys())):
        if total_result[k] <= b:
            return str(k)

    return str(0)

