def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])

    # Build cost matrix: costs[i][j] = cost for city i to connect to city j
    costs = [[0] * n for _ in range(n)]
    for i in range(n):
        row = list(map(int, lines[i+1].split()))
        idx = 0
        for j in range(n):
            if j != i:
                costs[i][j] = row[idx]
                idx += 1

    # Cannot form perfect matching if odd number of cities
    if n < 2 or n % 2 != 0:
        return '-1\n'

    def is_stable(mp):
        """Check if pairing mp is stable."""
        # Verify all pairings are mutual
        for i in range(n):
            if mp[mp[i]] != i:
                return False

        # Check for blocking pairs
        for i in range(n):
            current_partner = mp[i]
            current_cost = costs[i][current_partner]

            for j in range(i + 1, n):
                other_partner = mp[j]

                # If i and j are already paired, skip
                if other_partner == i:
                    continue

                swap_cost_i = costs[i][j]
                swap_cost_j = costs[j][i]
                current_cost_j = costs[j][other_partner]

                # Both prefer switching to each other - this is a blocking pair
                if swap_cost_i < current_cost and swap_cost_j < current_cost_j:
                    return False
        return True

    # Generate all perfect matchings using backtracking
    def generate_all_matchings(n):
        results = []
        paired = [False] * n

        def backtrack(result):
            if all(paired):
                results.append(dict(result))
                return

            first = None
            for i in range(n):
                if not paired[i]:
                    first = i
                    break

            for j in range(first + 1, n):
                if not paired[j]:
                    paired[first] = True
                    paired[j] = True
                    result[first] = j
                    result[j] = first
                    backtrack(result)
                    del result[first]
                    paired[first] = False
                    paired[j] = False

        backtrack({})
        return results

    matchings = generate_all_matchings(n)

    for mp in matchings:
        if is_stable(mp):
            result = '\n'.join([str(mp[i] + 1) for i in range(n)])
            return result + '\n'

    return '-1\n'

