class Parser:
    def __init__(self, s):
        self.expression = s.strip()
        self.pos = 0

    def parse(self):
        if not self.expression:
            return None
        node = self.parse_expression()
        return node

    def parse_expression(self):
        left = self.parse_term()
        while self.pos < len(self.expression):
            if self.expression[self.pos] == '+':
                self.pos += 1
                right = self.parse_term()
                return ('ADD', left, right)
            else:
                break
        return left

    def parse_term(self):
        if self.pos >= len(self.expression):
            return None

        if self.expression[self.pos].isdigit():
            start = self.pos
            while self.pos < len(self.expression) and self.expression[self.pos].isdigit():
                self.pos += 1
            return ('NUM', int(self.expression[start:self.pos]))

        if self.expression[self.pos] == '-':
            self.pos += 1
            left = self.parse_term()
            right = self.parse_term()
            left_val = int(self.expression[:self.pos].split('-')[0])
            right_val = int(self.expression[self.pos:].split('-')[0]) if '-' in self.expression[self.pos:] else 0
            return ('RANGE', left_val, right_val)

        if self.expression[self.pos] == '(':
            self.pos += 1
            inner = self.parse_expression()
            if self.pos < len(self.expression):
                start = self.pos
                while self.pos < len(self.expression) and self.expression[self.pos].isdigit():
                    self.pos += 1
                repeat = int(self.expression[start:self.pos])
                self.pos += 1  # skip ')'
                return ('REP', repeat, inner)
            else:
                raise ValueError("Missing closing parenthesis")

        raise ValueError(f"Unexpected character: {self.expression[self.pos]}")

def eval_range(l, r, memo, pow10_table):
    """Compute concatenation of all integers from l to r"""
    if l > r:
        return 0, 0

    total_len = 0
    result = 0

    for n in range(l, r + 1):
        d = len(str(n))
        result = (result * pow10_table[d] + n) % MOD
        total_len += d

    return (total_len, result)

def eval_node(node, memo, pow10_table):
    if node[0] == 'NUM':
        return (1, node[1])

    if node[0] == 'ADD':
        left_len, left_val = eval_node(node[1], memo, pow10_table)
        right_len, right_val = eval_node(node[2], memo, pow10_table)
        result = (left_val * pow10_table[right_len] + right_val) % MOD
        return (left_len + right_len, result)

    if node[0] == 'RANGE':
        l, r = node[1], node[2]
        total_len, result = eval_range(l, r, memo, pow10_table)
        return (total_len, result)

    if node[0] == 'REP':
        count, inner = node[1], node[2]
        inner_len, inner_val = eval_node(inner, memo, pow10_table)

        if count == 0:
            return (0, 0)

        # Compute value of repeated concatenation
        result = 0
        for _ in range(count):
            result = (result * pow10_table[inner_len] + inner_val) % MOD

        return (count * inner_len, result)

    raise ValueError(f"Unknown node type: {node[0]}")

