    k_inv = pow(k, MOD - 2, MOD)
    k2_inv = (k_inv * k_inv) % MOD

    # sum1 = sum_{i=1}^{n-1} k^{-i}
    # Using geometric series formula
    num1 = (1 - pow(k_inv, n - 1, MOD) + MOD) % MOD
    inv_den1 = pow(k - 1, MOD - 2, MOD)
    sum1 = num1 * inv_den1 % MOD

    s2 = 0
    if n > 2:
        if n % 2 == 0:
            # j goes from 2 to n-2, max(j,2j-n)=j, exponents: 2,4,...,n-2 for 2j-n
            N = n // 2 - 1
            if N > 0:
                num = k2_inv * (1 - pow(k2_inv, N, MOD) + MOD) % MOD
                inv_d = (1 - k2_inv + MOD) % MOD
                s2 = num * pow(inv_d, MOD - 2, MOD) % MOD
        else:
            # j goes from 1 to n-2 with specific structure
            N = (n - 1) // 2
            if N > 0:
                num = k_inv * (1 - pow(k2_inv, N, MOD) + MOD) % MOD
                inv_d = (1 - k2_inv + MOD) % MOD
                s2 = num * pow(inv_d, MOD - 2, MOD) % MOD

