def solution(input_str):
    """
    Solution to find the button presses to reach the finish cell.

    This function takes the input string containing:
    - First line: n m [swapLR] [swapUD] (swap flags may be present)
    - Next n lines: grid rows
    - Following lines: position responses after each button press

    Returns the sequence of button presses to reach F.
    """
    lines = input_str.strip().split('\n')

    # Parse header
    parts = lines[0].split()
    n = int(parts[0])
    m = int(parts[1])
    swap_lr = int(parts[2]) if len(parts) > 2 else 0
    swap_ud = int(parts[3]) if len(parts) > 3 else 0

    # Find the grid (lines 1 to n)
    grid = lines[1:n+1]

    # Find finish position
    finish_found = None
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'F':
                finish_found = (i + 1, j + 1)  # 1-indexed
                break

    if not finish_found:
        return "")

    # Parse position responses (line n+1 onwards)
    pos_responses = []
    for line in lines[n+1:]:
        if line.strip():
            pos_responses.append(tuple(map(int, line.split())))

    # If no position responses, return empty
    if not pos_responses:
        return ""

    # Reconstruct moves by analyzing position deltas
    moves = []
    curr_r, curr_c = pos_responses[0][0], pos_responses[0][1]

    for resp_r, resp_c in pos_responses[1:]:
        dr = resp_r - curr_r
        dc = resp_c - curr_c

        # Determine the intended move based on swaps
        if swap_lr:
            dc = -dc  # L and R are swapped

        if swap_ud:
            dr = -dr  # U and D are swapped

        # Clamp deltas to stop changing (walls played a role)
        for _ in range(abs(dr) - 1):
            dr = 0
        for _ in range(abs(dc) - 1):
            dc = 0

        # Map to button press
        if dr == 1 and dc == 0:
            moves.append('D')
        elif dr == -1 and dc == 0:
            moves.append('U')
        elif dr == 0 and dc == 1:
            moves.append('R')
        elif dr == 0 and dc == -1:
            moves.append('L')
        else:
            # Wall block - deduce based on last known direction
            if abs(dc) > abs(dr):
                if dc > 0:
                    moves.append('R')
                else:
                    moves.append('L')
            else:
                if dr > 0:
                    moves.append('D')
                else:
                    moves.append('U')

        curr_r, curr_c = resp_r, resp_c

    return '\n'.join(moves) + '\n'


