    prefix_sums = []
    for j in range(m):
        engs = sorted(engineers_for_size[j], reverse=True)
        ps = [0]
        for p in engs:
            ps.append(ps[-1] + p)
        # Pad to n+1 values (capped at total engineers)
        while len(ps) < n + 1:
            ps.append(ps[-1])
        prefix_sums.append(ps)

    # dp[k] = maximum expected value using exactly k T-shirts
    dp = [0.0] * (n + 1)

    # For each size, do knapsack-style DP update
    for ps in prefix_sums:
        for k in range(n, -1, -1):
            for j in range(k + 1):
                value = dp[k - j] + ps[j]
                if value > dp[k]:
                    dp[k] = value

    return f"{dp[n]:.12f}\n"

