from functools import lru_cache

def solution(txt):
    n, k, m = map(int, txt.strip().split())
    MOD = 10**9 + 7

    # State: (current_position, mask_of_visited_planets)
    # mask uses bit i to indicate if planet (i+1) has been visited
    @lru_cache(None)
    def count_ways(current, mask):
        # Remaining planets to visit after current position (excluding current from visited)
        visited_count = bin(mask).count('1')
        if visited_count + 1 == k:
            return 1  # All k planets visited

        total = 0
        limit = min(n, current + m)
        for y in range(1, limit + 1):
            if not (mask & (1 << (y - 1))):
                total = (total + count_ways(y, mask | (1 << (y - 1)))) % MOD

        return total

    result = 0
    for start in range(1, n + 1):
        result = (result + count_ways(start, 1 << (start - 1))) % MOD

    return str(result)

