def solution(input_string):
    lines = input_string.strip().split('\n')
    n, k = map(int, lines[0].split())
    A = list(map(int, lines[1].split()))

    # Check if max already >= k
    if A and max(A) >= k:
        return '0\n'

    # Compute prefix sum
    def take_prefix_sum(arr):
        n_ord = len(arr)
        if n_ord == 0:
            return []
        result = [arr[0]]
        for i in range(1, n_ord):
            result.append(result[-1] + arr[i])
        return result

    i = 1
    while True:
        A = take_prefix_sum(A)
        max_val = A[-1]  # Since prefix sum, max is always the last element
        if max_val >= k:
            return str(i) + '\n'
        i += 1

def solution(X):
    MOD = 10**9 + 7

    def S(n):
        s = str(n)
        sorted_s = ''.join(sorted(s))
        return int(sorted_s)

    X_int = int(X)
    total = 0

    for i in range(1, X_int + 1):
        total = (total + S(i)) % MOD

    return str(total)
